// A pull request's description, in the repository item popup, as this
// repository's own are written: `##` sections, a checked test plan, and the
// `---` / `_Generated by …_` sign-off. Only those few shapes are drawn as
// markdown; the rest of it stays text.
import assert from 'node:assert/strict'
import { mock, test } from 'node:test'
import './_polyfills.js'
import { templateText } from './_lit.js'

mock.module('../ui/view/code-highlight.js', { namedExports: { highlightedCode: () => null } })
mock.module('../ui/view/render.js', { namedExports: { render() {} } })
mock.module('../ui/view/dom.js', { namedExports: { report: null } })
const { renderHighlighted } = await import('../ui/view/render-finding.js')
const { flowText } = await import('../ui/view/format.js')

const shown = text => templateText(renderHighlighted(flowText(text)))

const BODY = `## Summary

After #972, the list still failed.

- **\`server-managed/pull-reviews.ts\`:** a team is no longer read.

## Test plan

- [x] New regression tests in \`tests/a.test.js\`:
  - Hung \`objstoreResources\` → ack still ships
- [ ] Checked in Chromium

https://claude.ai/code/session_015z4f1mKHytRAyvnbBvypvc

---
_Generated by [Claude Code](https://claude.ai/code/session_015z4f1mKHytRAyvnbBvypvc)_`

test('a pull request\'s headings, test plan and sign-off are drawn as such', () => {
  const text = shown(BODY)
  assert.match(text, /^<div class="md-heading" role="heading" aria-level=2>Summary<\/div><div class="para">After #972, the list still failed\.<\/div>/u)
  assert.match(text, /<strong><span class="inline-code">server-managed\/pull-reviews\.ts<\/span>:<\/strong> a team is no longer read\./u, 'a code chip inside bold')
  assert.match(text, /aria-level=2>Test plan<\/div>/u)
  assert.match(text, /<li class="md-task"><input type="checkbox" disabled \?checked=true><div class="para">New regression tests in <span class="inline-code">tests\/a\.test\.js<\/span>:<\/div><ul class="md-list"><li>Hung /u, 'a ticked item, its nested list inside it')
  assert.match(text, /<li class="md-task"><input type="checkbox" disabled \?checked=false>Checked in Chromium<\/li>/u)
  assert.match(text, /<hr class="md-rule"><div class="para"><em>Generated by <a href=https:\/\/claude\.ai\/code\/session_015z4f1mKHytRAyvnbBvypvc [^>]*>Claude Code<\/a><\/em><\/div>$/u, 'the rule on its own, the sign-off in italics, its link a link')
  assert.doesNotMatch(text, /##|\[x\]|\[ \]|---|_Generated/u)
  assert.equal(shown(BODY.replaceAll('\n', '\r\n')), text, 'the same with CRLF line endings, as GitHub\'s web editor saves them')
  assert.equal(templateText(renderHighlighted(BODY.replaceAll('\n', '\r\n'))), templateText(renderHighlighted(BODY)), 'and without flowText first')
})

test('a heading or a rule right after a list item ends the list', () => {
  assert.match(shown('- [x] done\n## Notes'), /<\/li><\/ul><div class="md-heading" role="heading" aria-level=2>Notes<\/div>$/u)
  assert.match(shown('- item\n---\nafter'), /<\/li><\/ul><hr class="md-rule"><div class="para">after<\/div>$/u)
})

test('each emphasis ends at its own closing underscore', () => {
  assert.equal(shown('_a_ and _b_, _one_ and _two_'), '<em>a</em> and <em>b</em>, <em>one</em> and <em>two</em>')
})

test('emphasis stays linear on a long line of openers that never close (ReDoS guard)', () => {
  // Each `_` here opens and none closes. A scan running past every later
  // underscore from each one took ~1.5s at 60KB and grows with the square;
  // this is 300KB, ~1ms now. A 2s ceiling cleanly separates them.
  const payload = '_a.'.repeat(100000)
  const t = performance.now()
  const text = shown(payload)
  const ms = performance.now() - t
  assert.ok(ms < 2000, `emphasis took ${ms.toFixed(0)}ms — possible ReDoS regression`)
  assert.equal(text, payload)
})

test('what isn\'t one of those shapes stays as written', () => {
  for (const text of ['snake_case_name and __init__', 'café_monde_ and 東京_駅_', 'नमस्ते_दुनिया_ and cafe\u0301_monde_', '#972 and #hashtag', '##\nDetails', 'a [ ] box mid-line', '1 _ 2 _ 3']) {
    assert.equal(shown(text), text, text)
  }
})
